 * as a WAV file in 'wav'.  Returns the WAV size in bytes, or a negative
 * errno.  'wav' must hold at least AI_VOICE_WAV_MAX bytes.
 */

int ai_voice_record(FAR uint8_t *wav, size_t wav_size, int seconds);

