/* 主机端自检：用 libri0.wav 跑 jx_encode / jx_decode，与 PC 参考产物对比 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "jx_codec.h"

static int16_t *read_wav16(const char *path, int *n_out)
{
  FILE *f = fopen(path, "rb");
  if (!f) { fprintf(stderr, "cannot open %s\n", path); return NULL; }
  unsigned char h[12];
  fread(h, 1, 12, f);
  int ch = 1, bits = 16;
  unsigned char ck[8];
  long data_off = -1; unsigned int data_sz = 0;
  while (fread(ck, 1, 8, f) == 8)
    {
      unsigned int sz = ck[4] | (ck[5] << 8) | (ck[6] << 16) | ((unsigned int)ck[7] << 24);
      if (!memcmp(ck, "fmt ", 4))
        {
          unsigned char fmt[16]; fread(fmt, 1, 16, f);
          ch = fmt[2] | (fmt[3] << 8);
          bits = fmt[14] | (fmt[15] << 8);
          if (sz > 16) fseek(f, sz - 16, SEEK_CUR);
        }
      else if (!memcmp(ck, "data", 4)) { data_off = ftell(f); data_sz = sz; break; }
      else fseek(f, sz + (sz & 1), SEEK_CUR);
    }
  if (data_off < 0 || bits != 16) { fprintf(stderr, "bad wav\n"); fclose(f); return NULL; }
  int frames = (int)(data_sz / (2 * ch));
  int16_t *out = malloc(sizeof(int16_t) * frames);
  fseek(f, data_off, SEEK_SET);
  for (int i = 0; i < frames; i++)
    {
      int16_t s[2] = {0, 0};
      for (int c = 0; c < ch; c++) fread(&s[c], 2, 1, f);
      out[i] = s[0];
    }
  fclose(f);
  fprintf(stderr, "wav: ch=%d bits=%d frames=%d\n", ch, bits, frames);
  *n_out = frames;
  return out;
}

int main(int argc, char **argv)
{
  if (argc < 3) { fprintf(stderr, "usage: %s in.wav out.idx\n", argv[0]); return 1; }
  int n = 0;
  int16_t *pcm = read_wav16(argv[1], &n);
  if (!pcm) return 1;

  int64_t *idx = NULL; int ntok = 0, Tt = 0;
  if (jx_encode(pcm, n, &idx, &ntok, &Tt) != 0) { fprintf(stderr, "encode fail\n"); return 1; }

  FILE *f = fopen(argv[2], "wb");
  int hdr[3] = {1, Tt, n};
  fwrite(hdr, 4, 3, f);
  fwrite(idx, 8, (size_t)ntok, f);
  fclose(f);

  float *rec = NULL;
  if (jx_decode(idx, Tt, n, &rec) != 0) { fprintf(stderr, "decode fail\n"); return 1; }

  fprintf(stderr, "rate=%s n=%d Tt=%d ntok=%d bits=%d\n",
          jx_rate_name(), n, Tt, ntok, jx_token_bits());
  fprintf(stderr, "timing: pre=%.1fms quant=%.1fms deq_attn=%.1fms dec=%.1fms total=%.1fms\n",
          jx_last_timing.pre_ms, jx_last_timing.quant_ms,
          jx_last_timing.deq_attn_ms, jx_last_timing.dec_ms, jx_last_timing.total_ms);
  double s = 0; for (int i = 0; i < n; i++) s += fabs(rec[i]);
  fprintf(stderr, "mean|rec|=%.5f\n", s / n);
  return 0;
}
