```c
static void conv1d_core(const float *W, const float *b, const float *xin, float *yout,
                        int Ci, int Co, int k, int stride, int pad, int groups, int T_in, int T_out, int dil) {
    int cpg  = Ci / groups;
    int copg = Co / groups;
    for (int co = 0; co < Co; co++) {
        int g = co / copg;
        float *yp = &yout[(size_t)co * T_out];
        if (b) { float bb = b[co]; for (int t = 0; t < T_out; t++) yp[t] = bb; }
        else   { memset(yp, 0, (size_t)T_out * sizeof(float)); }
        const int base_ci = g * cpg;
        for (int ci = 0; ci < cpg; ci++) {
            const float *xp = &xin[(size_t)(base_ci + ci) * T_in];
            const float *wr = &W[((size_t)co * cpg + ci) * k];
            if (stride == 1) {
                for (int kk = 0; kk < k; kk++) {
                    float wv = wr[kk];
                    int off = kk * dil - pad;
                    int ts = (-off + stride - 1) / stride;  /* stride=1 -> -off */
                    if (ts < 0) ts = 0;
                    int te = T_in - off;
                    if (te > T_out) te = T_out;
                    for (int t = ts; t < te; t++) yp[t] += xp[t + off] * wv;
                }
            } else {
                for (int kk = 0; kk < k; kk++) {
                    float wv = wr[kk];
                    int off = kk * dil - pad;
                    for (int t = 0, pos = off; t < T_out; t++, pos += stride)
                        if (pos >= 0 && pos < T_in) yp[t] += xp[pos] * wv;
                }
            }
        }
    }
