static int16_t *read_wav16(const char *path, int *n_out)
{
  FILE *f = fopen(path, "rb");
  if (!f) { fprintf(stderr, "cannot open %s\n", path); return NULL; }
  unsigned char h[12];
  fread(h, 1, 12, f);
  int ch = 1, bits = 16;
  unsigned char ck[8];
  long data_off = -1; unsigned int data_sz = 0;
  while (fread(ck, 1, 8, f) == 8)
    {
      unsigned int sz = ck[4] | (ck[5] << 8) | (ck[6] << 16) | ((unsigned int)ck[7] << 24);
      if (!memcmp(ck, "fmt ", 4))
        {
          unsigned char fmt[16]; fread(fmt, 1, 16, f);
          ch = fmt[2] | (fmt[3] << 8);
          bits = fmt[14] | (fmt[15] << 8);
          if (sz > 16) fseek(f, sz - 16, SEEK_CUR);
        }
      else if (!memcmp(ck, "data", 4)) { data_off = ftell(f); data_sz = sz; break; }
      else fseek(f, sz + (sz & 1), SEEK_CUR);
    }
  if (data_off < 0 || bits != 16) { fprintf(stderr, "bad wav\n"); fclose(f); return NULL; }
  int frames = (int)(data_sz / (2 * ch));
  int16_t *out = malloc(sizeof(int16_t) * frames);
  fseek(f, data_off, SEEK_SET);
  for (int i = 0; i < frames; i++)
    {
      int16_t s[2] = {0, 0};
      for (int c = 0; c < ch; c++) fread(&s[c], 2, 1, f);
      out[i] = s[0];
    }
  fclose(f);
  fprintf(stderr, "wav: ch=%d bits=%d frames=%d\n", ch, bits, frames);
  *n_out = frames;
  return out;
}

