static void snake_apply(float *x, const float *alpha, int n, int ch) {
    /* channels_last layout: element (i, c) lives at x[i*ch + c] */
    for (int c = 0; c < ch; c++) {
        float a = alpha[c] + XNN_EPS; float inv = 1.0f / a;
        /* 原来写了两次 sinf(a*v)（同一个参数），这里只算一次再平方：
         * 数学与数值完全等价，但把 sinf 调用次数减半（sinf 在板上是慢路径）。 */
        for (int i = 0; i < n; i++) { float v = x[i * ch + c]; float s = sinf(a * v); x[i * ch + c] = v + inv * (s * s); }
    }
}
