            int t1 = t0 + W; if (t1 > Tt) t1 = Tt;
            int a = t0 - JX_FB_HALO; if (a < 0) a = 0;
            int e = t1 + JX_FB_HALO; if (e > Tt) e = Tt;
            int w = e - a;
            T xs = t_alloc(3, (int[]){1, 1, w});
