  if (!t || t->nd != 2) { printf("skip %s\n", name); return 0; }
  int out = t->shape[0], in = t->shape[1], rows = 3;
  const float *W = &WT_DATA[t->off];
  float *x = malloc(sizeof(float) * (size_t)rows * in);
  float *y = malloc(sizeof(float) * (size_t)rows * out);
  float scale = 1.0f;
