#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "nn_ops.h"

static float rnd(int i)
{
  return (float)(((unsigned)(i * 1103515245u + 12345u) % 100003u)) / 100003.0f * 2.0f - 1.0f;
}

static void test_linear(const char *name, int in, int out, double *worst)
{
  int rows = 3;
  const float *W = W_(name);
  if (W == NULL) { printf("  W_ NULL %s\n", name); return; }
  float *x = malloc(sizeof(float) * (size_t)rows * in);
  float *y = malloc(sizeof(float) * (size_t)rows * out);
  for (int i = 0; i < rows * in; i++) x[i] = rnd(i) * 3.0f;
  if (jx_linear_i8(W, NULL, x, y, rows, in, out) != 0) { printf("  unavail %s\n", name); free(x); free(y); return; }
  double maxerr = 0, maxref = 0, sumerr = 0, sumref = 0;
  for (int r = 0; r < rows; r++)
    for (int o = 0; o < out; o++)
      {
        double ref = 0;
        for (int j = 0; j < in; j++) ref += (double)W[(size_t)o * in + j] * (double)x[(size_t)r * in + j];
        double err = fabs(ref - (double)y[(size_t)r * out + o]);
        if (err > maxerr) maxerr = err;
        if (fabs(ref) > maxref) maxref = fabs(ref);
        sumerr += err * err; sumref += ref * ref;
      }
  double rel = sqrt(sumerr / (sumref + 1e-30));
  if (rel > *worst) *worst = rel;
  printf("  L %-44s in=%-4d out=%-4d relRMS=%8.2e maxErr=%8.2e\n", name, in, out, rel, maxerr / (maxref + 1e-30));
  free(x); free(y);
}

static void test_conv(const char *name, int Ci, int Co, int k, int groups, double *worst)
{
  int NS = 64, pad = k / 2;
  const float *W = W_(name);
  if (W == NULL) { printf("  W_ NULL %s\n", name); return; }
  float *x = malloc(sizeof(float) * (size_t)Ci * NS);
  float *y = malloc(sizeof(float) * (size_t)Co * NS);
  for (int i = 0; i < Ci * NS; i++) x[i] = rnd(i) * 3.0f;
  T tx; tx.d = x; tx.len = Ci * NS; tx.ndim = 3; tx.shape[0] = 1; tx.shape[1] = Ci; tx.shape[2] = NS;
  T ty; memset(&ty, 0, sizeof(ty)); ty.d = y; ty.len = Co * NS; ty.ndim = 3;
  if (jx_conv1d_i8(W, NULL, &tx, &ty, Ci, Co, k, 1, pad, groups, NS, NS, 1) != 0)
    { printf("  unavail %s\n", name); free(x); free(y); return; }
  int cpg = Ci / groups, copg = Co / groups;
  double maxerr = 0, maxref = 0, sumerr = 0, sumref = 0;
  for (int co = 0; co < Co; co++)
    {
      int g = co / copg;
      for (int tt = 0; tt < NS; tt++)
        {
          double ref = 0;
          for (int ci = 0; ci < cpg; ci++)
            for (int kk = 0; kk < k; kk++)
              {
                int pos = tt + kk - pad;
                if (pos >= 0 && pos < NS)
                  ref += (double)W[((size_t)co * cpg + ci) * k + kk] * (double)x[(size_t)(g * cpg + ci) * NS + pos];
              }
          double err = fabs(ref - (double)y[(size_t)co * NS + tt]);
          if (err > maxerr) maxerr = err;
          if (fabs(ref) > maxref) maxref = fabs(ref);
          sumerr += err * err; sumref += ref * ref;
        }
    }
  double rel = sqrt(sumerr / (sumref + 1e-30));
  if (rel > *worst) *worst = rel;
  printf("  C %-44s Ci=%-4d Co=%-4d k=%d g=%-3d relRMS=%8.2e maxErr=%8.2e\n",
         name, Ci, Co, k, groups, rel, maxerr / (maxref + 1e-30));
  free(x); free(y);
}

int main(void)
{
  double worst = 0;
  int nl = 0, nc = 0;
  for (int i = 0; i < NW_TENSORS; i++)
    {
      const WT *t = &WT_TAB[i];
      if (t->nd == 2 && t->shape[0] >= 2 && t->shape[1] >= 2)
        { test_linear(t->name, t->shape[1], t->shape[0], &worst); nl++; }
      else if (t->nd == 3 && t->shape[1] > 1 && t->shape[0] % t->shape[1] == 0)
        { test_conv(t->name, t->shape[1], t->shape[0], t->shape[2], 1, &worst); nc++; }
      else if (t->nd == 3 && t->shape[1] == 1 && t->shape[0] >= 8)
        { test_conv(t->name, t->shape[0], t->shape[0], t->shape[2], t->shape[0], &worst); nc++; }
    }
  printf("=== tested %d linear, %d conv ; worst relRMS = %.3e ===\n", nl, nc, worst);
  return 0;
}
