     *     src(o) = (o + 0.5)/scale - 0.5 = (2o + 1 - scale) / (2*scale)
     * 是**精确有理数**；并且 src(o + scale) = src(o) + 1，即 (i0, frac) 以
     * scale 为周期。所以每个 call 只需算 scale 组 (i0, frac)（全整数运算），
     * 内层循环退化成 2 次读 + 2 次 madd + 1 次写。
     * 数值上与原来的 double 版本只差 frac 的 1 ulp（<1e-7），远小于音频量化。 */
    if (scale >= 1 && scale <= 32) {
        int   itab[32];
        float ftab[32];
        const int den = 2 * scale;
        for (int k = 0; k < scale; k++) {
            int num = 2 * k + 1 - scale;
            int i0  = num / den;
            int rem = num - i0 * den;
            if (rem < 0) { rem += den; i0 -= 1; }
            itab[k] = i0;
            ftab[k] = (float)rem / (float)den;
        }
        for (int bi = 0; bi < B; bi++) for (int c = 0; c < C; c++) {
            const float *xp = &x->d[((size_t)bi * C + c) * Tin];
            float       *yp = &y->d[((size_t)bi * C + c) * Tout];
            int off = 0;
            for (int o = 0; o < Tout; o += scale, off++) {
                for (int k = 0; k < scale; k++) {
                    int i0 = itab[k] + off;
                    int i1 = i0 + 1;
                    float f = ftab[k];
                    float v0 = (i0 < 0) ? xp[0] : (i0 >= Tin ? xp[Tin - 1] : xp[i0]);
                    float v1 = (i1 < 0) ? xp[0] : (i1 >= Tin ? xp[Tin - 1] : xp[i1]);
