 183:   {
 184:     float inv = 127.0f / mx;
 185:     for (int i = 0; i < n; i++)
 186:       {
 187:         float v = x[i] * inv;
 188:         int iv = (int)(v + (v >= 0.0f ? 0.5f : -0.5f));
 189:         if (iv > 127) { iv = 127; } else if (iv < -127) { iv = -127; }
 190:         q[i] = (signed char)iv;
 191:       }
 192:   }
 193:   for (int i = n; i < n16; i++) { q[i] = 0; }
