 * 编译成无分支的选择指令，控制流消失，调度器就能自由交错。
 * 数学完全等价：floor 仍是 floor，折叠仍是 sin^2(pi-u)=sin^2(u)。 */
static inline float jx_sinsq(float x)
{
  float r = x * JX_INV_PI_F;
  float k = (float)(int)r;
  float u;
  float t;
  float p;
  k -= (k > r) ? 1.0f : 0.0f;        /* 截断 -> floor，负数也正确（无分支） */
  u = x - k * JX_PI_F;               /* [0, pi) */
  t = JX_PI_F - u;
  u = (u > JX_HALF_PI_F) ? t : u;    /* 折叠到 [0, pi/2]（无分支） */
