/* ============================================================================
 * jx_fastmath.h - 快速超越函数（多项式/有理逼近），用于 snake / gelu / tanh。
 *
 * 动机（板端实测 2026-09-12）：newlib 的 sinf / erff / tanhf 是主要剩余热点，
 * 合计约 8.6 s / 50 s。这些函数的取值范围都有界，用固定次数的 Horner
 * 多项式即可达到远好于 int8 量化噪声（~1e-2）的精度。
 *
 * 精度（相对 libm，双精度对照拟合，全网实测最大绝对误差）：
 *   jx_sinsq  sin(x)^2    1.7e-09   （x 归约到 [0,pi]，再映射到 [0,pi/2]，11 阶）
 *   jx_tanhf  tanh(x)     4.4e-07   （|x|<=8；之外饱和到 +-1）
 *   jx_erff   erf(x)      4.6e-06   （|x|<=4；之外饱和到 +-1）
 *
 * 关掉的办法：编译期 -DJX_FASTMATH=0，退回 libm（用于做 A/B 数值对照）。
 * ========================================================================== */
#ifndef JX_FASTMATH_H
#define JX_FASTMATH_H

#include <math.h>

#ifndef JX_FASTMATH
#  define JX_FASTMATH 1
#endif

#if JX_FASTMATH

#define JX_PI_F      3.14159265358979323846f
#define JX_HALF_PI_F 1.57079632679489661923f
#define JX_INV_PI_F  0.31830988618379067154f

/* sin(x)^2。先把 x 归约到 [0,pi)，再利用 sin^2(pi-u)=sin^2(u) 折叠到 [0,pi/2]。
 * 多项式是 sin(u)^2 在 u in [0,pi/2] 上的最小二乘（Chebyshev 节点）拟合。
 *
 * 2026-09-12 第五轮：两处 if 改成无分支的 ?: 。这里数学完全等价（结果逐位不变），
 * 但取消了控制流：原来跨元素的调度被分支切断，现在 4 条
 * 独立的 Horner 链可以被编译器交错排布，隐藏延时。
 *
 * （備选，本轮未采用）用 cos^2 恒等式换成 w=v^2 的 8 阶多项式可再省 3 步，
 * 不过会把 m0（纯 fp32 基准）从“与参考逐字节相同”变成“1740 个 token 里 1 个不同”，为保留
 * 逐位一致的回归基线而不采用。 */
static inline float jx_sinsq(float x)
{
  float r = x * JX_INV_PI_F;
  float k = (float)(int)r;
  float u;
  float t;
  float p;
  k -= (k > r) ? 1.0f : 0.0f;        /* 截断 -> floor，负数也正确（无分支） */
  u = x - k * JX_PI_F;               /* [0, pi) */
  t = JX_PI_F - u;
  u = (u > JX_HALF_PI_F) ? t : u;    /* 折叠到 [0, pi/2]（无分支） */
  p =          -4.157437553e-13f;
  p = p * u +   6.631500918e-04f;
  p = p * u +  -4.687531765e-03f;
  p = p * u +   2.053761546e-03f;
  p = p * u +   4.268362097e-02f;
  p = p * u +   9.617141793e-04f;
  p = p * u +  -3.336593731e-01f;
  p = p * u +   6.431927373e-05f;
  p = p * u +   9.999935029e-01f;
  p = p * u +   2.557090515e-07f;
  p = p * u +  -1.662400773e-09f;
  return p;
}

/* tanh(x) = x * P(x^2) / Q(x^2)，y = x^2 的 [4/3] 有理逼近，x in [0,8]。 */
static inline float jx_tanhf(float x)
{
  float ax = fabsf(x);
  float y;
  float p, q, r;
  if (ax >= 8.0f) { return (x >= 0.0f) ? 1.0f : -1.0f; }
  y = ax * ax;
  p =          -5.858162427e-09f;
  p = p * y +   6.994668850e-06f;
  p = p * y +   2.673332299e-03f;
  p = p * y +   1.268952674e-01f;
  p = p * y +   9.999998926e-01f;
  q =           1.938164396e-04f;
  q = q * y +   2.275157832e-02f;
  q = q * y +   4.602268718e-01f;
  q = q * y +   1.0f;
  r = ax * p / q;
  return (x < 0.0f) ? -r : r;
}

/* erf(x)/x 在 x in [0,4] 上的 12 次 Horner 多项式（x>=0 时求值）。 */
static inline float jx_erff(float x)
{
  float ax = fabsf(x);
  float p, r;
  if (ax >= 4.0f) { return (x >= 0.0f) ? 1.0f : -1.0f; }
  p =          -6.286994730e-08f;
  p = p * ax +  1.753091160e-05f;
  p = p * ax + -4.084229889e-04f;
  p = p * ax +  4.224728578e-03f;
  p = p * ax + -2.442294364e-02f;
  p = p * ax +  8.363318006e-02f;
  p = p * ax + -1.620724344e-01f;
  p = p * ax +  1.348616816e-01f;
  p = p * ax +  3.018854509e-02f;
  p = p * ax +  2.940681450e-02f;
  p = p * ax + -3.814843455e-01f;
  p = p * ax +  3.802787563e-04f;
  p = p * ax +  1.128374718e+00f;
  r = ax * p;
  return (x < 0.0f) ? -r : r;
}

#else  /* !JX_FASTMATH */

static inline float jx_sinsq(float x) { float s = sinf(x); return s * s; }
static inline float jx_tanhf(float x) { return tanhf(x); }
static inline float jx_erff (float x) { return erff(x); }

#endif /* JX_FASTMATH */

#endif /* JX_FASTMATH_H */

